// ─── Benchmark accessor ───────────────────────────────────────────────────────
// Reads data/benchmarkSeries.json (generated by scripts/fetchBenchmarks.ts).
//
// The interface treats "unavailable" as a first-class state so the Performance
// UI can render a pending benchmark without special-casing. Adding the
// Nasdaq-100 total-return series later means dropping levels into the JSON —
// no UI change.

import raw from "./benchmarkSeries.json";

export interface BenchmarkLevel {
  date: string; // month end, YYYY-MM-DD
  level: number;
}

export interface Benchmark {
  key: string;
  name: string;
  symbol?: string;
  /** True when the series is a total-return (dividends reinvested) index. */
  totalReturn: boolean;
  available: boolean;
  sourceNote: string;
  unavailableReason?: string;
  levels: BenchmarkLevel[];
}

interface RawDoc {
  fetchedAt: string;
  benchmarks: Record<string, Benchmark>;
}

const doc = raw as unknown as RawDoc;

/** Last completed month end — today's partial month is not a month-end mark. */
function lastCompletedMonthEnd(today = new Date()): string {
  const firstOfThisMonth = new Date(
    Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1)
  );
  const prevMonthEnd = new Date(firstOfThisMonth.getTime() - 86_400_000);
  return prevMonthEnd.toISOString().slice(0, 10);
}

const CUTOFF = lastCompletedMonthEnd();

export const benchmarks: Benchmark[] = Object.values(doc.benchmarks).map((b) => ({
  ...b,
  // Yahoo stamps the in-progress month at its month end; including it would
  // compare a partial benchmark month against a completed portfolio month.
  levels: b.levels.filter((l) => l.date <= CUTOFF),
}));

export const benchmarkFetchedAt = doc.fetchedAt;

export function getBenchmark(key: string): Benchmark | undefined {
  return benchmarks.find((b) => b.key === key);
}

export function availableBenchmarks(): Benchmark[] {
  return benchmarks.filter((b) => b.available && b.levels.length > 1);
}

export function pendingBenchmarks(): Benchmark[] {
  return benchmarks.filter((b) => !b.available || b.levels.length <= 1);
}

/**
 * Month-over-month total returns (%) for a benchmark, restricted to a window.
 * Returns [] when the series can't support it, so callers degrade rather than
 * fabricate.
 */
export function benchmarkMonthlyReturns(
  key: string,
  fromDate: string,
  toDate: string
): { date: string; returnPct: number }[] {
  const b = getBenchmark(key);
  if (!b?.available) return [];
  const inWindow = b.levels
    .filter((l) => l.date >= fromDate && l.date <= toDate)
    .sort((a, z) => a.date.localeCompare(z.date));
  const out: { date: string; returnPct: number }[] = [];
  for (let i = 1; i < inWindow.length; i++) {
    const prev = inWindow[i - 1].level;
    if (!prev) continue;
    out.push({
      date: inWindow[i].date,
      returnPct: ((inWindow[i].level - prev) / prev) * 100,
    });
  }
  return out;
}

/** Cumulative total return (%) between two month-end dates. */
export function benchmarkCumulativeReturn(
  key: string,
  fromDate: string,
  toDate: string
): number | undefined {
  const b = getBenchmark(key);
  if (!b?.available) return undefined;
  const start = b.levels.find((l) => l.date === fromDate);
  const end = [...b.levels].reverse().find((l) => l.date <= toDate);
  if (!start || !end || !start.level) return undefined;
  return ((end.level - start.level) / start.level) * 100;
}
